import React, { useState, useRef, useEffect } from 'react';
import PaymentSuccessModal from './PaymentSuccessModal';
import API_CONFIG from '../config/api';
import './Payment.css';

function Payment({ user, notice, lastPaymentStatus, lastPaymentTx, onComplete, onGoHome }) {
  const [selectedPlan, setSelectedPlan] = useState('pro');
  const [provider, setProvider] = useState('mtn'); // 'mtn' | 'moov' | 'celtiis'
  const [msisdn, setMsisdn] = useState('');
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState('');
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const pollRef = useRef(null);

  // Vérifier si le paiement a été validé
  useEffect(() => {
    if (lastPaymentStatus === 'VALIDATED') {
      setShowSuccessModal(true);
    }
  }, [lastPaymentStatus]);

  const handleSuccessComplete = () => {
    setShowSuccessModal(false);
    // Rediriger vers l'application principale (tests et analyses)
    onComplete?.();
  };

  const submitPaymentRecord = async (reference) => {
    try {
      const payload = {
        username: user?.username || 'user',
        email: user?.email || '',
        transaction_id: reference,
        note: `${provider.toUpperCase()} ${selectedPlan}`
      };
      await fetch(`${API_CONFIG.BASE_URL}${API_CONFIG.ENDPOINTS.SUBMIT_PAYMENT}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
    } catch (e) {
      // non bloquant: l'admin peut valider manuellement au besoin
    }
  };

  // Intégration opérateurs (flow générique: initiate -> polling status)
  const handlePay = async () => {
    setProcessing(true);
    setError('');
    try {
      // Utiliser les constantes de l'API_CONFIG au lieu de reconstruire manuellement
      const endpointMap = {
        mtn: API_CONFIG.ENDPOINTS.MOMO_INITIATE,
        moov: API_CONFIG.ENDPOINTS.MOOV_INITIATE,
        celtiis: API_CONFIG.ENDPOINTS.CELTIIS_INITIATE
      };
      const endpoint = endpointMap[provider] || API_CONFIG.ENDPOINTS.MOMO_INITIATE;
      
      const res = await fetch(`${API_CONFIG.BASE_URL}${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        // msisdn côté backend est optionnel; on l'ajoutera plus tard si nécessaire
        body: JSON.stringify({ plan: selectedPlan, userId: user?.id })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Paiement indisponible');
      if (data.payment_url) {
        window.location.href = data.payment_url; // redirection provider
        return;
      }
      const { reference } = data;
      // Plutôt que de poller ici, rediriger vers la page d'instructions pour dépôt manuel et soumission ID
      // On laisse la validation admin faire foi, puis l'utilisateur utilisera le code d'accès reçu par email
      window.dispatchEvent(new CustomEvent('payment_instructions', { detail: { provider, plan: selectedPlan, reference } }));
    } catch (e) {
      setError(e.message);
    } finally {
      // S'assurer d'enlever le loader même en cas d'erreur
      setProcessing(false);
    }
  };

  const goBack = () => {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      onGoHome?.();
    }
  };

  const cancelProcessing = () => {
    if (pollRef.current) {
      clearInterval(pollRef.current);
      pollRef.current = null;
    }
    setProcessing(false);
  };

  return (
    <div className="payment-page">
      <header className="payment-header">
        <div className="brand-inline">
          <img src="/logos/BetAi.png" alt="BetAi" className="brand-mark" />
          <span className="brand-name">BetAi</span>
        </div>
        <div className="header-actions">
          <button className="btn-back" onClick={onGoHome}>Aller à l'accueil</button>
        </div>
      </header>

      <main className="payment-main">
        <div className="intro">
          <h1>Finaliser votre abonnement</h1>
          <p>Sélectionnez un plan pour activer votre compte</p>
        </div>
        {notice && (
          <div className="pay-error" role="alert" style={{marginTop:'0.75rem'}}>
            {notice}
            {lastPaymentTx && (
              <div style={{marginTop:'.35rem', opacity:.9}}>Dernier ID: <code>{lastPaymentTx}</code></div>
            )}
        </div>
        )}
        {error && <div className="pay-error">{error}</div>}

        <div className="plans-grid">
          <label className={`plan-card ${selectedPlan === 'starter' ? 'active' : ''}`}>
            <input type="radio" name="plan" value="starter" checked={selectedPlan === 'starter'} onChange={() => setSelectedPlan('starter')} />
            <div className="plan-title">Starter</div>
            <div className="plan-price"></div>
            <ul className="plan-features">
              <li>Analyse de base</li>
              <li>Simulation simple</li>
              <li>Support communautaire</li>
            </ul>
          </label>

          <label className={`plan-card featured ${selectedPlan === 'pro' ? 'active' : ''}`}>
            <input type="radio" name="plan" value="pro" checked={selectedPlan === 'pro'} onChange={() => setSelectedPlan('pro')} />
            <div className="plan-title">Pro</div>
            <div className="plan-price">10 000 FCFA / mois</div>
            <ul className="plan-features">
              <li>Prédictions avancées</li>
              <li>Simulations illimitées</li>
              <li>Tableau de bord avancé</li>
            </ul>
          </label>

          <label className={`plan-card ${selectedPlan === 'expert' ? 'active' : ''}`}>
            <input type="radio" name="plan" value="expert" checked={selectedPlan === 'expert'} onChange={() => setSelectedPlan('expert')} />
            <div className="plan-title">Expert</div>
            <div className="plan-price">14 900 FCFA / mois</div>
            <ul className="plan-features">
              <li>Accès complet + export</li>
              <li>Alertes anti‑piège</li>
              <li>Support prioritaire</li>
            </ul>
          </label>
        </div>

        <div className="amount-card" style={{marginTop: '1rem'}}>
          <div className="amount-label">Montant à payer</div>
          <div className="amount-display">{selectedPlan === 'pro' ? '10 000' : selectedPlan === 'expert' ? '14 900' : '7 000'} FCFA</div>
        </div>

        <div className="pay-methods">
          <div className="method-group">
            <label className={`method-card provider-mtn ${provider === 'mtn' ? 'active' : ''}`} onClick={() => setProvider('mtn')}>
              <input type="radio" name="provider" value="mtn" checked={provider === 'mtn'} onChange={() => setProvider('mtn')} />
              <img src="/logos/mtn.png" alt="MTN" />
              <span className="method-title">MTN MoMo</span>
            </label>
            <label className={`method-card provider-moov ${provider === 'moov' ? 'active' : ''}`} onClick={() => setProvider('moov')}>
              <input type="radio" name="provider" value="moov" checked={provider === 'moov'} onChange={() => setProvider('moov')} />
              <img src="/logos/moov.png" alt="Moov" />
              <span className="method-title">Moov Money</span>
            </label>
            <label className={`method-card provider-celtis ${provider === 'celtis' ? 'active' : ''}`} onClick={() => setProvider('celtiis')}>
              <input type="radio" name="provider" value="celtis" checked={provider === 'celtis'} onChange={() => setProvider('celtiis')} />
              <img src="/logos/celtis.jpeg" alt="Celtis" />
              <span className="method-title">Celtis Money</span>
            </label>
          </div>
        </div>

        <div className="pay-actions">
          <button className="btn-primary pay-btn" onClick={handlePay} disabled={processing}>
            {processing ? 'Traitement…' : 'Payer maintenant'}
          </button>
          {/* Suppression du bouton Passer pour forcer le paiement */}
        </div>

        
      </main>
      {processing && (
        <div className="pay-wait-overlay" role="dialog" aria-modal="true" aria-label="Paiement en cours">
          <div className="wait-card">
            <div className="spinner" aria-hidden="true"></div>
            <h3>En attente de paiement…</h3>
            <p className="wait-sub">Validez l'opération sur votre appareil {provider === 'mtn' || provider === 'moov' ? 'Mobile Money' : 'de paiement'}.</p>
            <div className="progress"><div className="bar"></div></div>
            <button className="btn-back" onClick={cancelProcessing} style={{marginTop:'0.75rem'}}>Annuler</button>
          </div>
        </div>
      )}
      {showSuccessModal && <PaymentSuccessModal isVisible={showSuccessModal} onComplete={handleSuccessComplete} />}
    </div>
  );
}

export default Payment;
